EDITS = [(DEV_OLD, ''), (GW_OLD, GW_NEW), (LOG_OLD, LOG_NEW)]


def main():
    path = os.path.join(ROOT, TARGET)
    if not os.path.exists(path):
        print('ERROR: %s not found next to this script.' % TARGET)
        print('       Run this patch from the ORRERY repo ROOT, not from')
        print('       documentation/. NOTHING was written.')
        return 1
    raw = open(path, 'rb').read()
    was_crlf = b'\r\n' in raw
    content = raw.decode('utf-8').replace('\r\n', '\n')
    actual = hashlib.md5(content.encode('utf-8')).hexdigest()
    if actual != FP_EXPECTED:
        print('ERROR: %s is not the file this patch was built against'
              % TARGET)
        print('       expected %s, found %s%s'
              % (FP_EXPECTED, actual, ' [CRLF]' if was_crlf else ''))
        print('       NOTHING was written. Undo is Discard Changes in '
              'GitHub Desktop.')
        return 1
    for old, new in EDITS:
        n = content.count(old)
        if n != 1:
            print('ANCHOR FAIL: expected 1 match, found %d: %r'
                  % (n, old[:60]))
            print('NOTHING was written. Undo is Discard Changes in '
                  'GitHub Desktop.')
            return 1
        content = content.replace(old, new, 1)
    if any(ord(c) > 127 for c in content):
        print('ERROR: the result would hold non-ASCII characters. NOTHING '
              'was written.')
        return 1
    out = content.encode('ascii')
    if was_crlf:
        out = out.replace(b'\n', b'\r\n')
    with open(path, 'wb') as handle:
        handle.write(out)
    print('ok  %s  (%d bytes%s)'
          % (TARGET, len(out), ', CRLF preserved' if was_crlf else ''))
    print('moved: Exhibit Store Editor, Developer Tools -> Gallery & Web')
    print('added: Store Writer Suite, Store Editor Suite')
    print('sorted: Gallery & Web -- offline run, its checkers indented and')
    print('        alphabetical, the live run, then the tools alphabetical')
    print('        (22 entries, none lost)')
    print('')
    print('Until the editor is pushed to the gallery, Exhibit Store Editor')
    print('and Store Editor Suite log "Not found: ..." and do nothing else.')
    print('Store Writer Suite works now.')
    print('')
    print('NEXT: python orrery_maintenance_run.py, then move this script')
    print('      into documentation/, commit and push.')
    return 0


if __name__ == '__main__':
    sys.exit(main())
